boxBlockFinale.source:
if (!instance_exists(obj_growtangle))
    instance_create(__view_get(e__VW.XView, 0) + 320, __view_get(e__VW.YView, 0) + 170, obj_growtangle);

if (!instance_exists(obj_moveheart))
    scr_moveheart();

scr_turntimer(90);
global.mnfight = 2;

perTurn.source:
if (healing_egg_con == 0)
{
    if (i_ex(obj_orange_enemy) && obj_orange_enemy.uppercut_life < 1)
    {
        __dc = instance_create(obj_orange_enemy.x, obj_orange_enemy.y, obj_dbulletcontroller);
        ...
        __dc.type = 314;
        __dc.difficulty = 8;
        with (obj_orange_enemy) uppercut_life = 5;
        scr_turntimer(360);
    }
    else
    {
        __dc = instance_create(x, y, obj_dbulletcontroller);
        ...
        __dc.type = 131;
        scr_turntimer(270);
    }
}
